import Mathlib
import Novelty.NeuralHodge.Defs
import Novelty.NeuralHodge.FVector

/-!
# Network Architecture Bounds

Bounds relating neural network architecture parameters to the
topological complexity of decision surfaces.
-/

open Finset BigOperators

/-! ## Region Bound Properties -/

/-
The network region bound is always positive.
-/
theorem network_region_bound_pos (arch : ReluNetArch) :
    0 < networkRegionBound arch := by
  exact Finset.prod_pos fun i _ => zaslavskyBound_pos _ _

/-
Wider layers give more linear regions.
-/
theorem network_region_bound_mono_width
    {n d : ℕ} {w₁ w₂ : Fin d → ℕ}
    {hp₁ : ∀ i, 0 < w₁ i} {hp₂ : ∀ i, 0 < w₂ i}
    {hn : 0 < n}
    (hw : ∀ i, w₁ i ≤ w₂ i) :
    networkRegionBound ⟨n, d, w₁, hp₁, hn⟩ ≤
    networkRegionBound ⟨n, d, w₂, hp₂, hn⟩ := by
  exact Finset.prod_le_prod' fun i _ => zaslavskyBound_mono_left ( hw i ) _

/-! ## Depth Amplification Theorem

The fundamental expressivity result: depth multiplicatively amplifies
the logarithm of the region count. A depth-L width-w network has
up to ((w+1)^n)^L = (w+1)^{nL} regions.
-/

/-
**Depth amplification**: a depth-L, width-w network has at most
    ((w+1)^n)^L linear regions. This is the Montúfar-Pascanu-Cho-Bengio
    bound, showing that depth is exponentially more efficient than width.
-/
theorem depth_amplification (n w L : ℕ) (hn : 0 < n) (hw : 0 < w) :
    networkRegionBound ⟨n, L, fun _ => w, fun _ => hw, hn⟩ ≤
    ((w + 1) ^ n) ^ L := by
  unfold networkRegionBound;
  rw [ ← Fin.prod_const ];
  gcongr;
  unfold layerRegionBound zaslavskyBound;
  rw [ add_pow ];
  gcongr;
  simp +zetaDelta at *;
  exact le_trans ( Nat.choose_le_pow _ _ ) ( Nat.le_mul_of_pos_right _ ( Nat.choose_pos ‹_› ) )

/-! ## Hodge Number Bounds -/

/-
The Hodge bound is at most 2^(total neurons) for any (p,q).
-/
theorem hodge_bound_le_two_pow (arch : ReluNetArch) (p q : ℕ) :
    hodgeBound arch p q ≤ 2 ^ arch.totalNeurons := by
  by_cases h : arch.numLayers ≥ 2;
  · -- In this case, apply the bounds to each term in the product.
    have h_bound : (arch.layerWidths ⟨0, by omega⟩).choose p * (arch.layerWidths ⟨arch.numLayers - 1, by omega⟩).choose q * ∏ i : Fin (arch.numLayers - 2), arch.layerWidths ⟨(i : ℕ) + 1, by omega⟩ ≤ 2 ^ (arch.layerWidths ⟨0, by omega⟩) * 2 ^ (arch.layerWidths ⟨arch.numLayers - 1, by omega⟩) * ∏ i : Fin (arch.numLayers - 2), 2 ^ (arch.layerWidths ⟨(i : ℕ) + 1, by omega⟩) := by
      gcongr;
      · rw [ ← Nat.sum_range_choose ];
        by_cases hp : p ≤ arch.layerWidths ⟨0, by omega⟩;
        · exact Finset.single_le_sum ( fun x _ => Nat.zero_le ( Nat.choose ( arch.layerWidths ⟨ 0, by linarith ⟩ ) x ) ) ( Finset.mem_range.mpr ( by linarith ) );
        · rw [ Nat.choose_eq_zero_of_lt ( not_le.mp hp ) ] ; norm_num;
      · rw [ ← Nat.sum_range_choose ];
        by_cases hq : q ≤ arch.layerWidths ⟨arch.numLayers - 1, by omega⟩;
        · exact Finset.single_le_sum ( fun x _ => Nat.zero_le _ ) ( Finset.mem_range.mpr ( Nat.lt_succ_of_le hq ) );
        · rw [ Nat.choose_eq_zero_of_lt ( not_le.mp hq ) ] ; norm_num;
      · exact le_of_lt ( Nat.recOn ( arch.layerWidths ⟨ _, _ ⟩ ) ( by norm_num ) fun n ihn => by rw [ pow_succ' ] ; linarith [ Nat.one_le_pow n 2 zero_lt_two ] );
    convert h_bound using 1;
    · unfold hodgeBound; aesop;
    · rcases arch with ⟨ n, d, w, hw, hn ⟩ ; rcases d with ( _ | _ | d ) <;> simp_all +decide [ Fin.prod_univ_succ, ReluNetArch.totalNeurons ] ;
      · contradiction;
      · contradiction;
      · rw [ ← pow_add, ← Finset.prod_pow_eq_pow_sum ];
        rw [ Fin.prod_univ_succ ] ; norm_num [ Fin.prod_univ_castSucc, pow_add ] ; ring!;
  · interval_cases _ : arch.numLayers <;> simp_all +decide [ hodgeBound ];
    · exact Nat.one_le_pow _ _ ( by decide );
    · grind

/-! ## Single Layer -/

/-
Single layer with w hyperplanes: the region bound equals the Zaslavsky bound.
-/
theorem single_layer_bound (n w : ℕ) (hn : 0 < n) (hw : 0 < w) :
    networkRegionBound ⟨n, 1, fun _ => w, fun _ => hw, hn⟩ =
    layerRegionBound n w := by
  exact Fin.prod_univ_one _

/-
The total number of neurons in a uniform-width network is w * L.
-/
theorem uniform_total_neurons (n w L : ℕ) (hn : 0 < n) (hw : 0 < w) :
    (⟨n, L, fun _ => w, fun _ => hw, hn⟩ : ReluNetArch).totalNeurons = w * L := by
  unfold ReluNetArch.totalNeurons; simp +decide [ mul_comm ] ;

/-! ## Zaslavsky Bound Power Bound -/

/-
The Zaslavsky bound satisfies Z(m, n) ≤ (m+1)^n.
    This is a polynomial bound on the region count.
-/
theorem zaslavskyBound_le_pow_succ (m n : ℕ) :
    zaslavskyBound m n ≤ (m + 1) ^ n := by
  induction' n with n ih generalizing m <;> induction' m with m ih' <;> simp_all +decide [ Nat.choose_succ_succ, zaslavskyBound ];
  · simp +arith +decide [ Finset.sum_range_succ' ];
  · simp_all +decide [ Nat.choose_succ_succ, Finset.sum_range_succ' ];
    rw [ Nat.pow_succ' ] at *;
    simp_all +decide [ Finset.sum_add_distrib, add_mul ];
    nlinarith [ ih m, pow_pos ( by linarith : 0 < m + 1 ) n, pow_le_pow_left' ( by linarith : m + 1 ≤ m + 1 + 1 ) n ]
